using Sprout.Graphics;

namespace Rodel.MinecraftLauncher.App.Features.Images;

/// <summary>One packaged image, with a label resolved in the active app language.</summary>
internal sealed class ImagePreset(string id, string folder, Func<string> label)
{
    internal string Id => id;
    internal string Name => label();
    internal string Path { get; } = System.IO.Path.Combine(AppContext.BaseDirectory, "Assets", folder, id + ".png");
    internal ImageSource Source => ImageSource.FromFile(Path);
}

